const themeButton = document.querySelector('.theme-toggle');
const themeMeta = document.querySelector('meta[name="theme-color"]');
const preference = window.matchMedia('(prefers-color-scheme: dark)');
let explicitTheme = false;
try { explicitTheme = ['light', 'dark'].includes(localStorage.getItem('theme')); } catch {}
function updateTheme(theme) {
document.documentElement.dataset.theme = theme;
if (themeMeta) themeMeta.content = theme === 'dark' ? '#202521' : '#f5f2e8';
if (themeButton) themeButton.setAttribute('aria-label', theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme');
}
updateTheme(document.documentElement.dataset.theme || 'light');
if (themeButton) {
themeButton.hidden = false;
themeButton.addEventListener('click', () => {
const theme = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
explicitTheme = true;
updateTheme(theme);
try { localStorage.setItem('theme', theme); } catch {}
});
}
preference.addEventListener('change', event => {
if (!explicitTheme) updateTheme(event.matches ? 'dark' : 'light');
});
if ('serviceWorker' in navigator && location.protocol !== 'file:') {
window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
}